// The bundled, deterministic demo: real Open-Meteo weather for Shanghai, June–September 2026,
// replayed with the playbook that was in force each month (v1 → v2 → v3 → v4). Generated by
// scripts/build-demo.mjs from the recorded fixtures; never edited by hand. It never reads or writes
// Busabase, and it never pretends to be a connection.
import { buildMonths, dayFromDecision } from "../view-model.js";
import { parseRuleCard } from "../walk-model.js";

export async function createDemoProvider() {
  const response = await fetch("demo-data.json", { headers: { accept: "application/json" } });
  if (!response.ok) throw new Error(`DEMO_UNAVAILABLE: demo-data.json ${response.status}`);
  const data = await response.json();
  const judge = data.judges[data.currentJudge];
  const months = buildMonths(
    data.decisions.map((fields) => dayFromDecision(fields, judge)),
    { judge, baselineHour: data.baselineHour, baselineByDate: data.baselineWeather, judgeByMonth: data.judgeByMonth },
  );
  const byMonth = new Map(months.map((month) => [month.month, month]));
  return {
    mode: "demo",
    async load() {
      return {
        mode: "demo",
        place: data.place,
        folderName: "遛狗不淋雨",
        judge,
        card: parseRuleCard(data.playbookMarkdown),
        playbookMarkdown: data.playbookMarkdown,
        baseline: { version: data.baselineVersion, hour: data.baselineHour },
        index: months.map((month) => ({
          month: month.month,
          days: month.summary.days,
          wet: month.summary.wet,
          versions: month.versions,
        })),
        closed: data.closed,
        judgeChanges: data.judgeChanges,
        translations: data.en,
        pending: null,
      };
    },
    async loadMonth(month) {
      return byMonth.get(month) || null;
    },
  };
}
